const data = $input.first().json?.data || {};
const weightChange = data.weightChange || {};
const startW = weightChange.start_weight || 0;
const endW = weightChange.end_weight || 0;
const diff = startW && endW ? (endW - startW).toFixed(1) : 'N/A';
const direction = diff < 0 ? 'lost' : diff > 0 ? 'gained' : 'maintained';

const report = [
  '=== GYMTRACKER WEEKLY REPORT ===',
  'Period: Last 7 days',
  '',
  'WEIGHT:',
  '  Start: ' + (startW || 'N/A') + ' kg',
  '  End: ' + (endW || 'N/A') + ' kg',
  '  Change: ' + (diff !== 'N/A' ? (diff > 0 ? '+' : '') + diff + ' kg ' + direction : 'No data'),
  '',
  'WORKOUTS: ' + (data.workoutsCompleted || 0) + ' sessions completed',
  'AVG CALORIES: ' + (data.avgDailyCalories || 0) + ' kcal/day',
  '',
  'Generated: ' + new Date().toISOString()
].join('\n');

return [{ json: { report_text: report, raw_data: data, generated_at: new Date().toISOString() } }];
